fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length, we can safely zip them
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x < y)
        .collect()
}